const awake = { notFlags: ['tonyPassedOut'] };
const asleep = { flags: ['tonyPassedOut'] };
const contestant = { flags: ['tonyChallengeStarted'] };
export const toniTableLayers = [
  { id: 'layer.mehana.tony_diploma', asset: 'tonyDiploma', left: 970, top: 467, width: 104, height: 33, zIndex: 9, hiddenWhenFlag: 'tonyDiplomaTaken' },
  { id: 'layer.mehana.tony_rakia_half', asset: 'tonyRakiaHalf', left: 1012, top: 415, height: 67, zIndex: 8, requirements: awake },
  { id: 'layer.mehana.tony_rakia_empty', asset: 'tonyRakiaEmptySide', left: 993, top: 433, width: 83, height: 28, zIndex: 8, requirements: asleep },
