    this.simpleAnim.moving = false;
    this.simpleAnim.pendingStop = false;
    this.simpleAnim.canExitToStop = false;
    this.simpleAnim.sequence = {
      steps: [
        { mode: "idle", duration: 0.45 },
        { mode: "start" },
        { mode: "loop", loops: 3 },
