      }
    } else {
      state.elapsed += dt;
      state.frameIndex = 0;
    }

    if (state.moving) {
      if (state.mode === "start" && finished) {
        state.lastMoveMultiplier = 0;
        state.lastMoveDx = 0;
        this.setSimpleAnimMode("loop", { direction: state.direction, moving: true });
