    if (step.mode === "loop" && frame) {
      sequence.loopFramesRemaining -= dt * this.simpleAnimFps(frame);
      if (sequence.loopFramesRemaining <= 0) this.advanceSimpleSequence();
      return;
    }
    if (frame && !frame.loop && finished) this.advanceSimpleSequence();
